from pathlib import Path
import json,urllib.request,urllib.parse,hashlib,zipfile,io,subprocess,base64
out=Path('ysm-memory-readonly');out.mkdir(exist_ok=True)
a=json.load(urllib.request.urlopen('https://mc.muxigame.com/api/v1/manifest',timeout=30));raw=urllib.request.urlopen(a['manifestUrl'],timeout=30).read();m=json.loads(raw)
rows=[]
for f in m['files']:
 if not f['path'].startswith('mods/') or not any(k in f['path'].lower() for k in ['ysm-2.','ysm-compat','muxi-performance','muxi-game-core','muxi-core']):continue
 u=f.get('url') or a['manifestUrl'].rsplit('/',1)[0]+'/files/'+urllib.parse.quote(f['path']);b=urllib.request.urlopen(u,timeout=90).read();z=zipfile.ZipFile(io.BytesIO(b)); rows.append({**f,'sha256':hashlib.sha256(b).hexdigest(),'sha1Matches':hashlib.sha1(b).hexdigest()==f['sha1'],'ysmMemoryRelatedEntries':[n for n in z.namelist() if any(k in n.lower() for k in ['ysmcompat','deadtexture','residencypool','previewcleanup'])]})
r={'version':m['pack']['version'],'manifestSha256':hashlib.sha256(raw).hexdigest(),'files':rows,'compatEntries':[f['path'] for f in m['files'] if 'ysm-compat' in f['path'].lower()]};(out/'public.json').write_text(json.dumps(r,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps(r,ensure_ascii=False))
s=r'''$ErrorActionPreference='Stop';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$r='C:\Users\Administrator\WorkSpace\muxigame\bmc5server';$f=@(Get-ChildItem -LiteralPath "$r\mods" -File|Where-Object{$_.Name -match 'ysm-2\.|ysm-compat|muxi-performance|muxi-core|muxi-game-core'}|ForEach-Object{@{name=$_.Name;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower()}});$l=@(Select-String -LiteralPath "$r\logs\debug.log" -Pattern 'ysm-compat|enableDeadTextureSweep|preview_reference|muxi.ysm.compat|Found valid mod file.*ysm-2'|Select-Object -First 15|ForEach-Object{@{line=$_.LineNumber;text=$_.Line}});@{files=$f;logs=$l}|ConvertTo-Json -Depth 5 -Compress'''
w='& ([scriptblock]::Create([Console]::In.ReadToEnd()))';p=subprocess.run(['ssh','-o','BatchMode=yes','-o','ConnectTimeout=8','administrator@<PRIVATE_HOST>','powershell','-NoProfile','-NonInteractive','-EncodedCommand',base64.b64encode(w.encode('utf-16-le')).decode()],input=s.encode(),capture_output=True,timeout=50);assert p.returncode==0,p.stderr.decode(errors='replace');j=json.loads(p.stdout.decode('utf-8-sig'));(out/'server.json').write_text(json.dumps(j,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps(j,ensure_ascii=False))
